async function api(path,options={}){const response=await fetch(path,options);let data;try{data=await response.json()}catch{throw Error('Máy chủ chưa trả về kết quả. Vui lòng thử lại.')}if(!response.ok){if(Array.isArray(data.detail))throw Error('Có trường bị trống, quá dài hoặc sai định dạng. Vui lòng kiểm tra lại.');throw Error(viError(data.detail||''))}return data}
const post=(path,body)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function transferDateText(value){if(!value)return 'Chưa có ngày giờ';const match=String(value).match(/^(\d{4})-(\d{2})-(\d{2})(?:T|\s)?(.*)$/);return match?match[3]+'/'+match[2]+'/'+match[1]+(match[4]?' '+match[4]:''):String(value)}
function paymentPeriodSummary(row){const matches=row.payment_period_evidence?.matches||[],texts=[...new Set(matches.map(match=>match.text))];return '<div class="fieldrow"><div><label>Kỳ thanh toán hóa đơn nước</label><b>'+esc(row.payment_period||'Chưa xác định')+'</b><p class="hint">'+(texts.length?'Lấy từ nội dung: '+esc(texts.join('; ')):'Chưa xác định được kỳ thanh toán từ nội dung; cần kiểm tra thêm.')+'</p></div><div><label>Thời gian chuyển khoản</label><b>'+esc(transferDateText(row.date))+'</b><p class="hint">Theo cột ngày giờ giao dịch trong tệp ngân hàng.</p></div></div>'}
function nameExtractionSummary(row){const info=row.name_extraction||{},entities=info.entities||[],names=row.extracted_names||[];const labels={'bank_field':'Trường tên trong nội dung ngân hàng','bank_field+ner':'Trường tên đã được nhận diện tự động','ner':'Tên nhận diện tự động'};return '<div class="innerdetails"><label>Tên trong nội dung chuyển tiền</label>'+(names.length?'<b>'+names.map(esc).join('; ')+'</b><p class="hint">'+[...new Set(entities.filter(entity=>names.includes(entity.name)).map(entity=>labels[entity.source]||'Nội dung chuyển tiền'))].map(esc).join('; ')+'. Tên này là gợi ý để kiểm tra, chưa xác định mã khách hàng.</p>':'<p class="hint">Chưa trích được tên đáng tin cậy từ nội dung. Bạn có thể nhập tên đã kiểm tra khi xác nhận.</p>')+(info.status==='unavailable'?'<p class="hint">Tính năng nhận diện tên tự động chưa sẵn sàng; các bước đối soát khác vẫn tiếp tục.</p>':'')+'</div>'}
async function action(button,work){if(button)button.disabled=true;try{return await work()}catch(error){toast(error.message,true)}finally{if(button)button.disabled=(button.classList.contains('needs-db')&&!dbReady)||button.dataset.stopping==='true'}}
function askConfirmation(title,text,label='Xác nhận'){if(confirmResolver)return Promise.resolve(false);confirmReturnFocus=document.activeElement;$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmAccept').textContent=label;$('confirmModal').classList.remove('hidden');$('confirmCancel').focus();return new Promise(resolve=>{confirmResolver=resolve})}
function finishConfirmation(answer){const resolve=confirmResolver;confirmResolver=null;$('confirmModal').classList.add('hidden');if(confirmReturnFocus?.isConnected)confirmReturnFocus.focus();resolve?.(answer)}
function selectTab(id){for(const button of document.querySelectorAll('[data-tab]')){const active=button.dataset.tab===id;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;$(button.dataset.tab).classList.toggle('hidden',!active)}$('pageTitle').textContent=pageInfo[id][0];$('breadcrumb').textContent=pageInfo[id][0];$('pageSubtitle').textContent=pageInfo[id][1];if(id==='database'&&dbReady)loadDatabaseTables().catch(error=>toast(error.message,true));if(id==='tasks')jobs().catch(error=>toast(error.message,true))}
function updateSelection(){for(const id of [...selectedIds]){const row=rows.get(id);if(row&&row.status!=='pending')selectedIds.delete(id)}$('bulkBar').classList.toggle('hidden',selectedIds.size===0);$('bulkCount').textContent=selectedIds.size+' giao dịch đã chọn';const eligible=[...rows.values()].filter(row=>row.status==='pending'&&row.customer_id);$('selectAll').disabled=!eligible.length;$('selectAll').checked=eligible.length>0&&eligible.every(row=>selectedIds.has(row.id));$('selectAll').indeterminate=eligible.some(row=>selectedIds.has(row.id))&&!$('selectAll').checked}
function showResults(){viewCleared=false;resultRequestId++;offset=0;selectedIds.clear();$('pendingCount').classList.remove('hidden');updateSelection()}
function clearResults(){viewCleared=true;resultRequestId++;offset=0;total=0;rows.clear();selectedIds.clear();selected=null;$('modalBg').classList.add('hidden');$('transactionRows').innerHTML='<tr><td colspan="7" class="empty">Đã xóa kết quả hiển thị. Bấm Làm mới để xem lại tệp đang chọn.</td></tr>';$('pageInfo').textContent='0 giao dịch';$('prevButton').disabled=true;$('nextButton').disabled=true;$('pendingCount').classList.add('hidden');updateSelection()}
async function stats(){if(!dbReady)return;const requestId=++statsRequestId,jobId=activeJob;const p=activeJob?'?job_id='+encodeURIComponent(activeJob):'';const data=await api('/stats'+p);if(requestId!==statsRequestId||jobId!==activeJob)return;lastStats=data;$('customerCount').textContent=data.customers.toLocaleString('vi-VN');$('patternCount').textContent=data.patterns.toLocaleString('vi-VN');$('pendingCount').textContent=data.pending_review.toLocaleString('vi-VN')+' chưa duyệt';$('fileTotal').textContent=data.transactions.toLocaleString('vi-VN');$('filePending').textContent=data.pending_review.toLocaleString('vi-VN');$('fileConfirmed').textContent=data.confirmed.toLocaleString('vi-VN');$('learningNotice').classList.toggle('hidden',!data.pending_learning);$('learningNoticeText').textContent=data.pending_learning+' xác nhận chưa hoàn tất việc học. Hệ thống sẽ tiếp tục từ các xác nhận đã lưu.'}
async function loadRows(){if(!dbReady||viewCleared)return;const requestId=++resultRequestId;if(!activeJob){rows.clear();$('transactionRows').innerHTML='<tr><td colspan="7" class="empty">Chọn tệp làm việc hoặc tải tệp ngân hàng để đối soát.</td></tr>';$('pageInfo').textContent='0 giao dịch';$('prevButton').disabled=true;$('nextButton').disabled=true;updateSelection();return}const p=new URLSearchParams({offset,limit:20,job_id:activeJob,q:$('resultQuery').value.trim()});if($('decisionFilter').value)p.set('decision',$('decisionFilter').value);if($('statusFilter').value)p.set('status',$('statusFilter').value);const result=await api('/transactions?'+p);if(viewCleared||requestId!==resultRequestId)return;if(result.total&&offset>=result.total){offset=Math.floor((result.total-1)/20)*20;return loadRows()}total=result.total;rows=new Map(result.items.map(row=>[row.id,row]));$('transactionRows').innerHTML=result.items.length?result.items.map(row=>'<tr><td class="selectcell">'+(row.status==='pending'&&row.customer_id?'<input type="checkbox" data-select-row="'+row.id+'" aria-label="Chọn giao dịch '+row.id+'" '+(selectedIds.has(row.id)?'checked':'')+'>':'')+'</td><td class="raw"><div class="rawline">'+esc(row.raw)+'</div><div class="rowmeta">'+(row.sheet?'Sheet '+esc(row.sheet)+' · ':'')+(row.row_index?'Dòng '+row.row_index:'Nhập trực tiếp')+' · '+'Chuyển khoản: '+esc(transferDateText(row.date))+(row.amount?' · '+row.amount.toLocaleString('vi-VN')+' ₫':'')+'</div></td><td class="paymentperiod"><span class="periodlabel">Kỳ thanh toán</span><b>'+esc(row.payment_period||'Chưa xác định')+'</b></td><td><b>'+esc(row.confirmed_customer_name||row.customer_name||'Chưa xác định')+'</b><div class="rowmeta">'+esc(row.confirmed_customer_id||row.customer_id||'')+'</div>'+(row.extracted_names?.length?'<div class="rowmeta">Tên trong nội dung: '+row.extracted_names.map(esc).join('; ')+'</div>':'')+'</td><td><b>'+pct(row.score)+'</b></td><td><span class="pill '+esc(row.status==='pending'?row.decision:row.status)+'">'+esc(row.status==='pending'?decisions[row.decision]:statuses[row.status])+'</span></td><td><button class="small" data-review="'+row.id+'">Kiểm tra</button></td></tr>').join(''):'<tr><td colspan="7" class="empty">Không có giao dịch phù hợp với bộ lọc.</td></tr>';$('pageInfo').textContent=total?`${offset+1}–${Math.min(offset+20,total)} / ${total.toLocaleString('vi-VN')} giao dịch`:'0 giao dịch';$('prevButton').disabled=offset===0;$('nextButton').disabled=offset+20>=total;updateSelection()}
async function refresh(){await Promise.all([stats(),loadRows()])}
function identifierEvidence(evidence){const owners=evidence.confirmed_identifier_owners;if(!owners||!Object.keys(owners).length)return '';const labels={'id':'Mã khách hàng','contract':'Hợp đồng','bound-id':'Số đã xác nhận','code':'Mã chữ/số'};return '<details class="innerdetails"><summary>Định danh trong lịch sử</summary><p class="hint">Một số hoặc mã dùng chung cần thêm bằng chứng. Các mã chỉ tới khách hàng khác nhau cần kiểm tra thủ công.</p><div class="tablewrap"><table><thead><tr><th>Loại</th><th>Mã / số</th><th>Khách hàng đã xác nhận</th></tr></thead><tbody>'+Object.entries(owners).map(([token,ids])=>{const split=token.indexOf(':');return '<tr><td>'+esc(labels[token.slice(0,split)]||'Định danh')+'</td><td>'+esc(token.slice(split+1))+'</td><td>'+ids.map(esc).join(', ')+'</td></tr>'}).join('')+'</tbody></table></div></details>'}
function orderedEvidence(history){const comparison=history.numeric_comparison;if(!comparison)return '';return '<p class="hint">HD là hợp đồng; TKThe là thẻ người trả tiền. Đối chiếu số theo vai trò và đúng thứ tự trong mẫu.</p><div class="tablewrap"><table><thead><tr><th>Vị trí</th><th>Hiện tại</th><th>Lịch sử</th><th>Loại số</th><th>Đối chiếu</th></tr></thead><tbody>'+comparison.ordered_comparison.map(row=>'<tr><td>'+esc(row.slot)+(row.history_slot!=null&&row.history_slot!==row.slot?' → '+esc(row.history_slot):'')+'</td><td>'+esc(row.query_value)+'</td><td>'+esc(row.history_value??'—')+'</td><td>'+esc(numericTypes[row.type]||row.type)+'</td><td>'+(!row.same_role?'Khác vai trò':row.exact?'Trùng đầy đủ':row.variable_reference?'Tham chiếu thay đổi':'Khác giá trị')+'</td></tr>').join('')+'</tbody></table></div><p class="hint">Mẫu nội dung '+(comparison.template_compatible?'tương thích':'khác cấu trúc')+'; hợp đồng '+(comparison.contract_conflict?'khác nhau':comparison.aligned_contracts.length?'khớp chính xác':'chưa có bằng chứng khớp')+'.</p>'+(comparison.code_alignment_complete===false?'<p class="hint">Chưa đối chiếu được mã chữ/số hoặc số cơ sở theo đúng thứ tự. Hiện tại: '+esc((comparison.query_codes||[]).map(code=>code[1]).join(', ')||'Không có')+'. Lịch sử: '+esc((comparison.history_codes||[]).map(code=>code[1]).join(', ')||'Không có')+'.</p>':'')}
function customerAutocomplete(id,optionsId,nameId){let timer,version=0;$(id).oninput=()=>{const requestId=++version;clearTimeout(timer);if(nameId)$(nameId).value='';timer=setTimeout(async()=>{try{const value=$(id)?.value||'',items=await api('/customers?q='+encodeURIComponent(value));if(requestId!==version||!$(optionsId))return;$(optionsId).innerHTML=items.map(item=>'<option value="'+esc(item.id)+'">'+esc(item.name)+' · '+item.pattern_count+' mẫu</option>').join('');const exact=items.find(item=>item.id===value);if(exact&&nameId&&$(nameId))$(nameId).value=exact.name}catch{}},230)}}
function showReview(row){if(!row)return;selected=row;const evidence=row.evidence||{},history=evidence.matched_pattern?evidence:evidence.nearest_history||{},detected=row.normalization?.customer_ids||[];const suggested=row.customer_id||(detected.length===1&&detected[0].length<=100?detected[0]:'');$('reviewBody').innerHTML='<div class="buttons"><b>'+esc(row.confirmed_customer_name||row.customer_name||'Chưa xác định khách hàng')+'</b><span class="pill '+esc(row.decision)+'">'+pct(row.score)+' · '+esc(decisions[row.decision])+'</span></div><p class="hint">'+esc(evidence.reason_vi||'Chưa đủ bằng chứng để ghép; cần kiểm tra nội dung và khách hàng.')+'</p>'+paymentPeriodSummary(row)+paymentModeSummary(row)+nameExtractionSummary(row)+sharedTemplateSummary(history)+'<div class="twopane"><div><label>Giao dịch đang đối soát</label>'+ (row.sheet?'<p class="hint">Sheet '+esc(row.sheet)+(row.row_index?' · Dòng '+row.row_index:'')+(row.reference?' · Tham chiếu '+esc(row.reference):'')+'</p>':'')+'<div class="rawfull">'+esc(row.raw)+'</div></div><div><label>'+(evidence.matched_pattern?'Mẫu lịch sử đã khớp':'Mẫu gần nhất trong lịch sử')+'</label><div class="rawfull">'+esc(history.matched_pattern||'Chưa có mẫu phù hợp trong lịch sử.')+'</div>'+(history.pattern_source?'<p class="hint">'+esc(history.pattern_source.file||'')+(history.pattern_source.row?' · Dòng '+esc(history.pattern_source.row):'')+'</p>':'')+'</div></div>'+(row.status==='pending'?'<form id="reviewForm"><div class="divider"></div><h3>Xác nhận khách hàng để học</h3>'+paymentFields('reviewPayment',row,true)+'<div class="fieldrow"><div><label for="correctId">Mã khách hàng</label><input id="correctId" maxlength="100" required value="'+esc(suggested)+'" list="customerOptions"><datalist id="customerOptions"></datalist></div><div><label for="correctName">Tên khách hàng / bí danh đã kiểm tra</label><input id="correctName" maxlength="300" required value="'+esc(row.customer_name||row.extracted_name||'')+'"></div></div>'+(row.extracted_name?'<div class="buttons"><button id="useExtractedName" class="small" type="button">Dùng tên trong nội dung</button></div>':'')+'<p class="hint">Khách hàng mới sẽ được thêm khi xác nhận. Nội dung này sẽ trở thành một mẫu trong lịch sử của khách hàng.</p><div class="buttons"><button id="acceptReview" class="primary" type="submit">Xác nhận & học</button><button id="rejectReview" class="danger" type="button">Không ghép khách hàng này</button></div></form>':'<p class="hint">'+esc(statuses[row.status])+(row.learned?' · '+esc(row.confirmed_customer_id||''):'')+'</p>')+identifierEvidence(evidence.confirmed_identifier_owners?evidence:history)+(history.numeric_comparison?'<details id="numberDetails" class="innerdetails"><summary>Đối chiếu số theo đúng thứ tự</summary>'+orderedEvidence(history)+'</details>':'')+(history.matched_template?'<details id="templateDetails"><summary>Nội dung & cấu trúc đối chiếu</summary><label>Mẫu trong lịch sử</label><pre>'+esc(history.matched_template)+'</pre><label>Mẫu giao dịch hiện tại</label><pre>'+esc(history.query_template||row.normalization?.template||'')+'</pre>'+(history.match_steps_vi?'<ol>'+history.match_steps_vi.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol>':'')+'</details>':'');$('modalBg').classList.remove('hidden');$('closeModal').focus();if(row.status==='pending'){$('reviewForm').onsubmit=event=>{event.preventDefault();action(event.submitter,()=>feedback(true))};$('rejectReview').onclick=()=>action($('rejectReview'),()=>feedback(false));customerAutocomplete('correctId','customerOptions','correctName');if($('useExtractedName'))$('useExtractedName').onclick=()=>{$('correctName').value=row.extracted_name}}}
async function feedback(accept){const row=selected;if(!row)return;const id=accept?$('correctId').value.trim():null;if(accept&&!id)throw Error('Nhập hoặc chọn mã khách hàng trước khi xác nhận.');await post('/feedback',{transaction_id:row.id,accepted:accept,correct_customer_id:id,customer_name:accept?$('correctName').value.trim():'',...(accept?paymentData('reviewPayment'):{})});$('modalBg').classList.add('hidden');selectedIds.delete(row.id);toast(accept?'Đã xác nhận và bổ sung vào kiến thức.':'Đã ghi nhận từ chối ghép khách hàng này.');await refresh()}
function setExportLinks(){for(const [id,suffix] of [['resultXlsx','/results.xlsx'],['resultCsv','/csv.zip'],['learningCsv','/learning.zip']]){const element=$(id);element.classList.toggle('disabled',!activeJob);if(activeJob)element.href='/export/'+encodeURIComponent(activeJob)+suffix;else element.removeAttribute('href')}}
function jobStage(job){
  if(job.status!=='running')return '';
  const summary=job.summary||{};
  if(summary.phase==='reading')return '<p class="hint">Đang đọc tệp giao dịch…</p>';
  if(summary.phase==='classifying')return '<p class="hint">Đang đối soát sheet <b>'+esc(summary.current_sheet)+'</b>'+(summary.current_row?' · Dòng '+esc(summary.current_row):'')+'. Kết quả được cập nhật theo từng nhóm.</p>';
  return '';
}
function sheetSummary(job){
  const counts=job.summary?.sheet_counts||{},skipped=job.summary?.skipped_sheets||[],kind=job.kind==='knowledge_import'?'confirmed':'raw';
  const reasons={confirmed_layout:'dữ liệu đã gán nhãn, dùng mục Học dữ liệu mới',raw_layout:'sheet ngân hàng chưa gán nhãn, dùng mục Đối soát',unsupported_layout:'không nhận diện được bố cục giao dịch',ambiguous_layout:'có nhiều cột cùng vai trò, cần làm rõ tiêu đề'};
  const roles={raw:'nội dung',date:'ngày giờ',credit:'ghi có',debit:'ghi nợ',amount:'số tiền',customer_id:'mã khách hàng',customer_name:'tên khách hàng',payer:'ngân hàng',reference:'tham chiếu'};
  const corrections=skipped.some(item=>['unsupported_layout','ambiguous_layout'].includes(item.reason));
  return (Object.keys(counts).length?'<details><summary>Giao dịch theo sheet</summary>'+Object.entries(counts).map(([name,count])=>'<div class="hint">'+esc(name)+' · '+(Number(count)?Number(count).toLocaleString('vi-VN')+' dòng':'Chưa có kết quả')+'</div>').join('')+'</details>':'')+
    (skipped.length?'<details open><summary>'+skipped.length+' sheet được bỏ qua</summary>'+skipped.map(item=>'<div class="hint"><b>'+esc(item.sheet)+'</b> · '+esc(reasons[item.reason]||item.reason)+(item.missing_columns?.length?' · Chưa tìm được cột: '+item.missing_columns.map(esc).join(', '):'')+(item.ambiguous_columns?.length?' · Cột trùng vai trò: '+item.ambiguous_columns.map(role=>esc(roles[role]||role)).join(', '):'')+'</div>').join('')+(corrections?'<p class="hint">Nếu sheet có giao dịch, chỉnh theo mẫu: tiêu đề trên một dòng, mỗi dòng là một giao dịch, không gộp ô. Sheet tổng hợp không cần chuyển đổi. Các sheet phù hợp vẫn được xử lý.</p><a class="button small" href="/templates/'+kind+'.xlsx">Tải bố cục mẫu '+(kind==='raw'?'đối soát':'đã xác nhận')+'</a>':'')+'</details>':'');
}
function rowErrorSummary(job){
  const count=job.summary?.row_error_count||0;
  if(!count)return '';
  const samples=(job.summary.row_errors||[]).slice(0,20),stages={read:'Đọc dữ liệu',prepare:'Chuẩn bị nội dung',learn:'Học kiến thức',classify:'Đối soát'};
  return '<details><summary>'+Number(count).toLocaleString('vi-VN')+' dòng lỗi đã bỏ qua</summary><p class="hint">Các dòng còn lại tiếp tục được xử lý. Sửa các dòng lỗi trong tệp nguồn rồi nhập lại khi cần.</p><div class="tablewrap"><table><thead><tr><th>Sheet</th><th>Dòng trong tệp</th><th>Bước xử lý</th><th>Nguyên nhân</th></tr></thead><tbody>'+samples.map(issue=>'<tr><td>'+esc(issue.sheet)+'</td><td>'+esc(issue.row_index??('Không xác định · vị trí XML '+(issue.row_position??'—')))+'</td><td>'+esc(stages[issue.stage]||issue.stage)+'</td><td>'+esc(viError(issue.error))+'</td></tr>').join('')+'</tbody></table></div>'+(count>samples.length?'<p class="hint">Hiển thị '+samples.length+' dòng đầu. CSV chứa toàn bộ danh sách lỗi.</p>':'')+'<div class="buttons"><a class="button small" href="/jobs/'+encodeURIComponent(job.id)+'/errors.csv">Tải danh sách dòng lỗi CSV</a></div></details>';
}
async function jobs(){jobItems=(await api('/jobs')).filter(job=>job.kind!=='benchmark');const imports=jobItems.find(job=>job.kind==='knowledge_import'&&['queued','running','cancelling'].includes(job.status));activeImportId=imports?.id||null;$('stopImportButton').classList.toggle('hidden',!imports);$('stopImportButton').dataset.stopping=String(imports?.status==='cancelling');$('stopImportButton').disabled=imports?.status==='cancelling';$('stopImportButton').textContent=imports?.status==='cancelling'?'Đang dừng…':'Dừng nhập';const files=jobItems.filter(job=>job.kind==='batch_classify');const previous=activeJob;if(!files.some(job=>job.id===activeJob))activeJob=files[0]?.id||null;$('jobFilter').innerHTML=files.length?files.map(job=>'<option value="'+esc(job.id)+'">'+esc(job.filename||'Tệp ngân hàng')+' · '+esc(statuses[job.status])+' · '+job.progress+' dòng</option>').join(''):'<option value="">Chưa có tệp làm việc</option>';$('jobFilter').value=activeJob||'';if(previous!==activeJob&&!viewCleared){offset=0;resultRequestId++;selectedIds.clear()}setExportLinks();const active=jobItems.filter(job=>['queued','running','cancelling'].includes(job.status));$('taskCount').classList.toggle('hidden',!active.length);$('taskCount').textContent=active.length;$('jobs').innerHTML=jobItems.length?jobItems.map(job=>{const running=['queued','running','cancelling'].includes(job.status),file=job.kind==='batch_classify';return '<div class="job"><div class="jobtop"><div><b>'+esc(job.filename||kinds[job.kind]||'Tác vụ')+'</b><div class="rowmeta">'+esc(kinds[job.kind]||'Xử lý')+' · '+esc(job.created_at?.slice(0,16).replace('T',' ')||'')+'</div></div><span class="pill '+esc(job.status)+'">'+esc(statuses[job.status]||job.status)+(job.status==='completed'&&job.summary?.row_error_count?' · có dòng lỗi':'')+'</span></div>'+(running?'<div class="jobprogress"><span></span></div>':'')+'<div class="hint">Đã xử lý '+job.progress.toLocaleString('vi-VN')+' dòng'+(job.summary?.counts?.learned!=null?' · '+job.summary.counts.learned+' dòng được học':'')+'</div>'+jobStage(job)+sheetSummary(job)+rowErrorSummary(job)+(job.error?'<div class="joberror">'+esc(viError(job.error))+'</div>':'')+'<div class="buttons">'+(running?'<button class="small danger" data-stop-job="'+esc(job.id)+'" '+(job.status==='cancelling'?'disabled':'')+'>Dừng xử lý</button>':'')+(file&&job.progress?'<button class="small" data-view-job="'+esc(job.id)+'">Xem kết quả</button><a class="button small" href="/export/'+esc(job.id)+'/results.xlsx">Tải Excel</a><a class="button small" href="/export/'+esc(job.id)+'/csv.zip">CSV theo sheet (ZIP)</a><a class="button small" href="/export/'+esc(job.id)+'/learning.zip">CSV đã học (ZIP)</a>':'')+(!running?'<button class="small danger" data-delete-job="'+esc(job.id)+'">Xóa tệp làm việc</button>':'')+'</div></div>'}).join(''):'<div class="empty">Chưa có tệp làm việc. Tải tệp để bắt đầu.</div>';return active.length>0}
async function stopJob(id){if(!id)return;const result=await post('/jobs/'+encodeURIComponent(id)+'/cancel',{});toast(result.status==='cancelling'?'Đang dừng xử lý. Phần đã hoàn tất được giữ.':result.status==='cancelled'?'Đã dừng tác vụ.':'Tác vụ đã kết thúc.');await jobs();if(dbReady)await refresh()}
async function pollJobs(){if(polling)return;polling=true;try{let active=true;while(active){active=await jobs();if(dbReady)await refresh();if(active)await new Promise(resolve=>setTimeout(resolve,2000))}}catch(error){toast(error.message,true)}finally{polling=false}}
async function queued(result,classifying=false){if(classifying){activeJob=result.job_id;showResults();selectTab('workspace')}await jobs();toast(classifying?'Đã nhận tệp đối soát. Kết quả xuất hiện theo từng đợt.':'Đã nhận tệp học. Theo dõi tại Tác vụ xử lý.');if(dbReady)await refresh();pollJobs()}
const tableLabels={customers:'Khách hàng',customer_aliases:'Tên / bí danh khách hàng',payer_entities:'Người / tài khoản trả tiền',payment_templates:'Mẫu nội dung dùng chung',transaction_patterns:'Liên kết mẫu với khách hàng',numeric_features:'Giá trị số đã học',numeric_slots:'Vị trí số trong mẫu',retrieval_postings:'Khóa tìm kiếm',knowledge_receipts:'Dấu xác nhận đã học',knowledge_metadata:'Thông tin kho kiến thức',hard_negatives:'Ghép sai đã bị từ chối'};
const columnLabels={template_id:'Mã mẫu dùng chung',payment_mode:'Kiểu thanh toán',provider_kind:'Loại đơn vị thu hộ',provider_name:'Đơn vị thu hộ',display_name:'Tên mẫu chung',description:'Ghi chú',link_count:'Số liên kết',customer_count:'Số khách hàng',created_at:'Ngày tạo',id:'Mã',canonical_name:'Tên khách hàng',normalized_name:'Tên chuẩn hóa',value_digest:'Dấu kiểm tra giá trị',token_digest:'Dấu khóa tìm kiếm',pattern_count:'Số mẫu đã học',customer_id:'Mã khách hàng',alias:'Bí danh',normalized_alias:'Bí danh chuẩn hóa',confidence:'Độ tin cậy lịch sử',payer_name:'Người / tài khoản trả tiền',payer_type:'Loại người trả tiền',seen_count:'Số lần gặp',last_seen:'Cập nhật gần nhất',last_period:'Kỳ gần nhất',payer_id:'Mã người trả tiền',fingerprint:'Dấu nhận diện',normalized_text:'Nội dung chuẩn hóa',template_text:'Mẫu nội dung',raw_example:'Giao dịch mẫu',source_file:'Nguồn dữ liệu',source_row:'Dòng nguồn',example_date:'Ngày giao dịch mẫu',structure:'Thứ tự chữ/số',segments:'Nội dung đã tách theo thứ tự',embedding:'Vector ngữ nghĩa',embedding_model:'Bộ mã hóa ngữ nghĩa',pattern_id:'Mã mẫu',slot_index:'Vị trí số',slot_confidence:'Độ tin cậy vị trí',numeric_value:'Giá trị số',numeric_type:'Loại số',exact_value_confidence:'Độ tin cậy giá trị',missing_count:'Số lần vắng mặt',token:'Khóa tìm kiếm',weight:'Trọng số',transaction_fingerprint:'Dấu nội dung ghép sai',count:'Số lần',period:'Kỳ',key:'Khóa',value:'Giá trị'};
const previewColumns={customers:['id','canonical_name','pattern_count'],payment_templates:['id','display_name','payment_mode','template_text','customer_count'],transaction_patterns:['id','customer_id','template_id','payment_mode','raw_example'],payer_entities:['id','customer_id','payer_name','payer_type','seen_count'],numeric_features:['id','pattern_id','numeric_value','numeric_type','slot_index']};
function databaseMeta(){return databaseTables.find(table=>table.name===$('databaseTable').value)}
function fieldLabel(name){return columnLabels[name]||name}
function fieldText(name,value){if(value==null)return '—';if(typeof value==='object')return JSON.stringify(value,null,2);if(name==='payment_mode')return paymentLabels[value]||value;if(name==='provider_kind')return providerLabels[value]||value;if(name==='numeric_type')return numericTypes[value]||value;if(name==='payer_type')return {bank:'Ngân hàng / kênh trả tiền',account:'Tài khoản / thẻ'}[value]||value;if(typeof value==='boolean')return value?'Có':'Không';return String(value)}
async function loadDatabaseTables(){if(!dbReady)return;const requestId=++databaseTableRequestId,tables=await api('/database/tables');if(requestId!==databaseTableRequestId)return;const previous=$('databaseTable').value;databaseTables=tables;const main=['customers','payment_templates','transaction_patterns','payer_entities','customer_aliases','numeric_features'],groups=[['Hồ sơ & mẫu đã học',main],['Dữ liệu hỗ trợ',tables.map(table=>table.name).filter(name=>!main.includes(name))]];$('databaseTable').innerHTML=groups.map(([label,names])=>'<optgroup label="'+esc(label)+'">'+names.map(name=>{const table=tables.find(item=>item.name===name);return table?'<option value="'+esc(name)+'">'+esc(tableLabels[name]||name)+' · '+table.count.toLocaleString('vi-VN')+' bản ghi</option>':''}).join('')+'</optgroup>').join('');$('databaseTable').value=tables.some(table=>table.name===previous)?previous:'customers';await loadDatabaseRows()}
async function loadDatabaseRows(){const meta=databaseMeta();if(!dbReady||!meta)return;const requestId=++databaseRequestId,currentOffset=databaseOffset,p=new URLSearchParams({offset:currentOffset,limit:20,q:$('databaseQuery').value.trim()});if(databaseCustomerScope)p.set('customer_id',databaseCustomerScope);if(databaseTemplateScope)p.set('template_id',databaseTemplateScope);$('databasePrev').disabled=true;$('databaseNext').disabled=true;$('databaseHeaders').innerHTML='';$('databaseRows').innerHTML='<tr><td colspan="6" class="empty">Đang tải dữ liệu…</td></tr>';const result=await api('/database/tables/'+encodeURIComponent(meta.name)+'/rows?'+p);if(requestId!==databaseRequestId)return;if(result.total&&currentOffset>=result.total){databaseOffset=Math.floor((result.total-1)/20)*20;return loadDatabaseRows()}const columns=previewColumns[meta.name]||meta.columns.slice(0,5).map(column=>column.name);$('databaseHeaders').innerHTML='<tr>'+columns.map(name=>'<th>'+esc(fieldLabel(name))+'</th>').join('')+'<th></th></tr>';$('databaseRows').innerHTML=result.items.length?result.items.map(row=>'<tr>'+columns.map(name=>{const text=fieldText(name,row[name]);return '<td class="dbcell"><div class="rawline">'+esc(text.length>180?text.slice(0,180)+'…':text)+'</div></td>'}).join('')+'<td class="dbactions"><button class="small" data-database-row="'+esc(row[meta.primary_key])+'">Chi tiết</button></td></tr>').join(''):'<tr><td colspan="'+(columns.length+1)+'" class="empty">Không có dữ liệu phù hợp.</td></tr>';$('databasePageInfo').textContent=result.total?`${currentOffset+1}–${Math.min(currentOffset+20,result.total)} / ${result.total.toLocaleString('vi-VN')} bản ghi`:'0 bản ghi';$('databasePrev').disabled=currentOffset===0;$('databaseNext').disabled=currentOffset+20>=result.total;$('databaseHint').textContent=['customers','transaction_patterns','payment_templates'].includes(meta.name)?'Mở Chi tiết để xem các mẫu, sửa hoặc xóa kiến thức đã xác nhận.':'Dữ liệu hỗ trợ chỉ xem; các thay đổi được thực hiện qua hồ sơ khách hàng và mẫu.';$('databaseScope').classList.toggle('hidden',!databaseCustomerScope&&!databaseTemplateScope);$('databaseScopeText').textContent=databaseCustomerScope?'Các mẫu của khách hàng '+databaseCustomerScope:databaseTemplateScope?'Các liên kết của mẫu chung '+databaseTemplateScope:''}
